  const currentPath = window.location.pathname;
  const currentHostname = window.location.hostname;
  
  // 1. If they are already on /tw/, they are a Taiwan user. Set the flag.
  if (currentPath.startsWith("/tw")) {
    localStorage.setItem("is_taiwan_user", "true");
  }

  const userOptedOut = localStorage.getItem("disable_tw_redirect") === "true";

  // 2. If they manually click the "English" toggle from /tw/ back to /, set the bypass
  if (document.referrer.includes(currentHostname + "/tw")) {
    localStorage.setItem("disable_tw_redirect", "true");
  }

  // 3. Only run if they aren't on /tw, not staging, haven't opted out, AND haven't been checked yet
  const alreadyChecked = localStorage.getItem("ip_checked") === "true";

  if (!currentPath.startsWith("/tw") && currentHostname !== "jolly-nonogon-415573.framer.app" && !userOptedOut && !alreadyChecked) {
    
    const triggerRedirect = () => {
      localStorage.setItem("is_taiwan_user", "true"); 
      const cleanPath = currentPath === "/" ? "" : currentPath;
      window.location.replace("https://disantinowater.com/tw" + cleanPath + window.location.search);
    };

    const markAsChecked = () => {
      localStorage.setItem("ip_checked", "true");
    };

    fetch('https://get.geojs.io/v1/ip/country.json')
      .then(r => r.ok ? r.json() : Promise.reject())
      .then(d => { 
        markAsChecked(); // Mark as checked regardless of country
        if (d.country === 'TW') triggerRedirect(); 
      })
      .catch(() => {
        fetch('https://ipapi.co/json/')
          .then(r => r.ok ? r.json() : Promise.reject())
          .then(d => { 
            markAsChecked(); // Mark as checked regardless of country
            if (d.country_code === 'TW') triggerRedirect(); 
          })
          .catch(e => console.error('Both IP services failed'));
      });
  }


